import * as T from 'three';
import {createTreeImpostor} from './world-tree-impostor.js';
import {inside,area,distance,centroid} from './world-geometry.js';
import {vegetationViewDistance,treeViewRange,treeDetailLevel} from './vegetation-view.js';
export function buildFlora(scene,renderer,data,nearSource,farSource,blocked){
 let seed=32149;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};const positions=[],mapped=data.features.filter(f=>f.properties.layer==='tree');for(const f of mapped)positions.push([...f.geometry.coordinates,7+rand()*5,rand()*6.28]);
 const greens=data.features.filter(f=>f.properties.layer==='vegetation'&&f.geometry.type==='Polygon');for(const f of greens){const ring=f.geometry.coordinates[0],a=Math.abs(area(ring)),tags=f.properties.tags||{},c=centroid(ring),wood=/wood|forest|scrub/.test(Object.values(tags).join(' '));let n=Math.min(42,Math.floor(a/(wood?95:210)));if(a<75)n=0;const xs=ring.map(p=>p[0]),zs=ring.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minZ=Math.min(...zs),maxZ=Math.max(...zs);for(let tries=0,added=0;tries<n*8&&added<n;tries++){const p=[minX+rand()*(maxX-minX),minZ+rand()*(maxZ-minZ)];if(!inside(p,ring)||f.geometry.coordinates.slice(1).some(h=>inside(p,h))||blocked(p)||positions.some(q=>distance(p,q)<6))continue;positions.push([...p,(wood?9:6)+rand()*7,rand()*6.28]);added++;}}
 const batches=[],shadowBatches=[],wind={value:0};nearSource.updateMatrixWorld(true);farSource.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(nearSource),height=bounds.max.y-bounds.min.y,origin=new T.Matrix4().makeTranslation(-(bounds.max.x+bounds.min.x)/2,-bounds.min.y,-(bounds.max.z+bounds.min.z)/2);
 const impostor=createTreeImpostor(renderer,scene,farSource,origin,positions.length);
 const windShader=shader=>{shader.uniforms.uWind=wind;shader.vertexShader='uniform float uWind;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\ntransformed.x+=sin(uWind*.55+instanceMatrix[3].x*.07+position.y)*.006*max(0.,position.y-1.);');};
 for(const [lod,source] of [nearSource,farSource].entries())source.traverse(o=>{if(!o.isMesh)return;const leaf=/leav/i.test(o.material.name),geo=o.geometry.clone().applyMatrix4(origin.clone().multiply(o.matrixWorld)),mat=o.material.clone();mat.envMapIntensity=.36;mat.metalness=0;mat.roughness=1;mat.side=T.DoubleSide;mat.alphaTest=leaf?.28:.15;mat.transparent=false;mat.alphaToCoverage=true;mat.normalScale?.setScalar(leaf?.42:.65);mat.onBeforeCompile=shader=>{if(leaf)windShader(shader);shader.fragmentShader=shader.fragmentShader.replace('#include <roughnessmap_fragment>','#include <roughnessmap_fragment>\nroughnessFactor='+ (leaf?'.68+.24':'.74+.2')+'*roughnessFactor;');};mat.customProgramCacheKey=()=>leaf?'leaf-v7':'bark-v7';
  const mesh=new T.InstancedMesh(geo,mat,positions.length);mesh.count=0;mesh.frustumCulled=false;mesh.receiveShadow=true;mesh.castShadow=false;scene.add(mesh);batches.push({lod,mesh});
  // A separate, unmodified tree mesh supplies stable shadows. It is independent
  // of view culling and render LOD, preventing canopy shadows from popping.
  if(lod===1){const shadow=new T.InstancedMesh(geo,mat,positions.length);shadow.count=0;shadow.frustumCulled=false;shadow.castShadow=true;shadow.layers.set(2);scene.add(shadow);shadowBatches.push(shadow);}
 });
 const frustum=new T.Frustum(),matrix=new T.Matrix4(),lastProjection=new T.Matrix4(),sphere=new T.Sphere(),dummy=new T.Object3D(),last=new T.Vector3(Infinity,0,0),lastQuaternion=new T.Quaternion(),shadowPosition=new T.Vector3(Infinity,0,0),states=new Uint8Array(positions.length).fill(1);let stamp=-1,high=true;
 const place=(mesh,list)=>{let n=0;for(const index of list){const p=positions[index];dummy.position.set(p[0],.06,p[1]);dummy.rotation.set(0,p[3],0);dummy.scale.setScalar(p[2]/height);dummy.updateMatrix();mesh.setMatrixAt(n,dummy.matrix);mesh.setColorAt(n,new T.Color().setHSL(.26+(index%11)*.002,.09,.82+(index%5)*.025));n++;}mesh.count=n;mesh.instanceMatrix.needsUpdate=true;if(mesh.instanceColor)mesh.instanceColor.needsUpdate=true;};
  return{count:positions.length,setQuality(v){high=v;stamp=-1;},update(t,camera){wind.value=t;const projectionChanged=!lastProjection.equals(camera.projectionMatrix);if(stamp>=0&&!projectionChanged&&t-stamp<.12)return;if(stamp>=0&&!projectionChanged&&camera.position.distanceToSquared(last)<.12&&camera.quaternion.angleTo(lastQuaternion)<.018)return;stamp=t;last.copy(camera.position);lastQuaternion.copy(camera.quaternion);lastProjection.copy(camera.projectionMatrix);camera.updateMatrixWorld();frustum.setFromProjectionMatrix(matrix.multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse));const groups=[[],[],[]],viewRange=treeViewRange(camera.position.y,high);for(let i=0;i<positions.length;i++){const p=positions[i],d=Math.hypot(p[0]-camera.position.x,p[1]-camera.position.z);if(d>viewRange)continue;sphere.center.set(p[0],p[2]*.55,p[1]);sphere.radius=p[2]*.82;if(d>25&&!frustum.intersectsSphere(sphere))continue;const viewDistance=vegetationViewDistance(d,camera.position.y-p[2]*.55,camera.fov);states[i]=treeDetailLevel(states[i],viewDistance,high);groups[states[i]].push(i);}for(const b of batches)place(b.mesh,groups[b.lod]);impostor.update(groups[2],positions,camera,height);
   // Shadow casters do not disappear together at an arbitrary camera height.
   if(camera.position.distanceToSquared(shadowPosition)>36){shadowPosition.copy(camera.position);const shadowList=[];for(let i=0;i<positions.length;i++){const p=positions[i];if(Math.hypot(p[0]-camera.position.x,p[1]-camera.position.z)<145)shadowList.push(i);}for(const mesh of shadowBatches)place(mesh,shadowList);renderer.shadowMap.needsUpdate=true;}
 }};
}
